from __future__ import absolute_import, division, print_function,\
    unicode_literals

from future import standard_library
standard_library.install_aliases()


class SerialConnectionException(Exception):
    """
        Any Errors with serial connection
    """
    pass


class DeviceNotDetectedException(Exception):
    """
        Module is not connected
    """
    pass


class IPAddressNotAssigned(Exception):
    """
        IP not assigned to dongle by network
    """
    pass


class IPInterfaceNotFoundException(Exception):
    """
        IP interface for dongle not found
    """
    pass


class ATCommandFailedException(Exception):
    """
        AT Command Failed
    """
    pass


class DeviceNotAttachedException(Exception):
    """
        dongle not attached
    """
    pass


class PPPInterfaceNotFound(Exception):
    """
    PPP Interface Not Found
    """
    pass


class PPPConnectScriptFailedError(Exception):
    """
    PPP Connect Script Failed Error
    """
    pass


class ModemHungupError(Exception):
    """
    Modem Hung-up Error
    """
    pass
